Here is the commit message:
sunos: fix syntax error introduced in 76d831e4

Moving around the code for #754 inadvertently introduced a syntax error
in a SunOS-only code path.

The syntax error didn't actually manifest at build time because
the #elif it was wrapped in was, alas, wrong as well.

Here is the root cause:
The bug was caused by a syntax error introduced when the code was rearranged in a previous commit, specifically due to the incorrect use of `#elif` instead of `else if`, which prevented the SunOS-specific error handling code from being compiled correctly. This led to the failure to handle the `EAI_MEMORY` error condition properly for SunOS systems.

Here is the patch:

 static void uv__getaddrinfo_done(struct uv__work* w, int status) {
   uv_getaddrinfo_t* req;
   struct addrinfo *res;
   size_t hostlen;

   req = container_of(w, uv_getaddrinfo_t, work_req);
   uv__req_unregister(req->loop, req);

   res = req->res;
   req->res = NULL;

   (void) &hostlen;  /* Silence unused variable warning. */
   hostlen = 0;
 #if defined(__sun)
   if (req->hostname != NULL)
     hostlen = strlen(req->hostname);
 #endif

   /* See initialization in uv_getaddrinfo(). */
   if (req->hints)
     free(req->hints);
   else if (req->service)
     free(req->service);
   else if (req->hostname)
     free(req->hostname);
   else
     assert(0);

   req->hints = NULL;
   req->service = NULL;
   req->hostname = NULL;

   if (status == -UV_ECANCELED) {
     assert(req->retcode == 0);
     req->retcode = UV_ECANCELED;
     uv__set_artificial_error(req->loop, UV_ECANCELED);
     req->cb(req, -1, NULL);
     return;
   }

   if (req->retcode == 0) {
     req->cb(req, 0, res);
     return;
   }

   if (req->retcode == EAI_NONAME)
     uv__set_sys_error(req->loop, ENOENT);
 #if defined(EAI_NODATA)  /* Newer FreeBSDs don't have EAI_NODATA. */
   else if (req->retcode == EAI_NODATA)
     uv__set_sys_error(req->loop, ENOENT);
-#elif defined(__sun)
-  if (req->retcode == EAI_MEMORY && hostlen >= MAXHOSTNAMELEN) {
+#endif
+#if defined(__sun)
+  else if (req->retcode == EAI_MEMORY && hostlen >= MAXHOSTNAMELEN)
     uv__set_sys_error(req->loop, ENOENT);
 #endif
   else {
     req->loop->last_err.code = UV_EADDRINFO;
     req->loop->last_err.sys_errno_ = req->retcode;
   }

   req->cb(req, -1, res);
 }



